import { z } from "zod";

// ================================
// USER
// ================================

// Validate a complete user object
export const userSchema = z.object({
  user_id: z.string().uuid(),
  auth_id: z.string().min(1).max(255),
  firstname: z.string().trim().min(1).max(100),
  surname: z.string().trim().min(1).max(100),
  username: z.string().trim().min(3).max(30),
  email: z.string().trim().email().max(254),

  role_id: z.string().uuid().nullable().optional(),
  createdAt: z.coerce.date().optional(),
});

// Validate data when creating a user
// user_id is generated by Sequelize.
// role_id is omitted to prevent public role assignment.
export const createUserSchema = z.object({
  auth_id: z.string().trim().min(1).max(255),
  firstname: z.string().trim().min(1).max(100),
  surname: z.string().trim().min(1).max(100),
  username: z.string().trim().min(3).max(30),
  email: z.string().trim().email().max(254),
  password: z
    .string()
    .min(8, "Password must be at least 8 characters")
    .optional(),
});

// Validate data when updating a user
export const updateUserSchema = z
  .object({
    firstname: z.string().trim().min(1).max(100).optional(),
    surname: z.string().trim().min(1).max(100).optional(),
    username: z.string().trim().min(3).max(30).optional(),
    email: z.string().trim().email().max(254).optional(),
  })
  .refine((data) => Object.keys(data).length > 0, {
    message: "At least one field must be provided",
  });

// ================================
// ROLE
// ================================

export const roleSchema = z.object({
  role_id: z.string().uuid(),
  name: z.enum(["user", "admin"]),
});

export const createRoleSchema = z.object({
  name: z.enum(["user", "admin"]),
});

// ================================
// QUIZ QUESTION
// ================================

export const questionSchema = z
  .object({
    question: z.string().trim().min(1).max(1000),
    options: z.array(z.string().trim().min(1).max(500)).min(2).max(10),
    correctAnswer: z.string().trim().min(1).max(500),
  })
  .refine((question) => question.options.includes(question.correctAnswer), {
    message: "Correct answer must match one of the options",
    path: ["correctAnswer"],
  });

// ================================
// QUIZ
// ================================

// Validate a complete quiz object
export const quizSchema = z.object({
  id: z.string().uuid(),
  title: z.string().trim().min(1).max(255),
  category: z.string().trim().min(1).max(100),
  group_id: z.string().uuid(),
  creator_id: z.string().uuid(),
  questions: z.array(questionSchema).min(1),
  createdAt: z.coerce.date(),
});

// Validate data when creating a quiz
// id and createdAt are generated by Sequelize.
export const createQuizSchema = z.object({
  title: z.string().trim().min(1).max(255),
  category: z.string().trim().min(1).max(100),
  group_id: z.string().uuid(),
  questions: z.array(questionSchema).min(1),
});

// ================================
// QUIZ RESULT
// ================================

export const quizResultSchema = z
  .object({
    id: z.string().uuid(),
    quiz_id: z.string().uuid(),
    user_id: z.string().uuid(),
    score: z.number().int().min(0),
    total_questions: z.number().int().positive(),
    createdAt: z.coerce.date(),
  })
  .refine((result) => result.score <= result.total_questions, {
    message: "Score cannot exceed total questions",
    path: ["score"],
  });

// Validate data when submitting a quiz result
// The authenticated user_id should be assigned by the backend.
export const createQuizResultSchema = z
  .object({
    quiz_id: z.string().uuid(),
    score: z.number().int().min(0),
    total_questions: z.number().int().positive(),
  })
  .refine((result) => result.score <= result.total_questions, {
    message: "Score cannot exceed total questions",
    path: ["score"],
  });

// ================================
// GROUP
// ================================

export const groupSchema = z.object({
  id: z.string().uuid(),
  name: z.string().trim().min(1).max(255),
  invite_code: z.string().trim().min(1).max(100).nullable(),
  owner_id: z.string().uuid(),
  createdAt: z.coerce.date(),
});

// Validate data when creating a group
// id, invite_code and createdAt can be generated by the backend.
export const createGroupSchema = z
  .object({
    name: z
      .string()
      .trim()
      .min(1, "Please provide a group name")
      .max(100, "Group name must not exceed 100 characters"),
  })
  .strict();

// ================================
// GROUP MEMBER
// ================================

export const groupMemberSchema = z.object({
  id: z.string().uuid(),
  group_id: z.string().uuid(),
  user_id: z.string().uuid(),
  role: z.enum(["member", "admin", "owner"]),
  createdAt: z.coerce.date(),
});

// Validate data when adding a group member
export const createGroupMemberSchema = z.object({
  group_id: z.string().uuid(),
  user_id: z.string().uuid(),
  role: z.enum(["member", "admin", "owner"]).default("member"),
});
